/**
 * Keep health data out of Android's automatic backups (docs/architecture.md: "Automatic
 * Google backup disabled for the DB; manual encrypted export/restore").
 *
 * android/ is generated by `npx cap add android` and git-ignored, so this patch is a
 * script rather than a committed file. Idempotent: run it after every add/sync
 * (`npm run android:sync` does).
 *
 * - allowBackup="false" and fullBackupContent="false": no Google Drive backup, no adb backup.
 * - dataExtractionRules (Android 12+): allowBackup alone no longer stops device-to-device
 *   transfer, so exclude every domain from both cloud backup and device transfer.
 * - versionName and versionCode from package.json, and the release signing config
 *   (scripts/android-gradle.mjs).
 * - The Even launcher icon (resources/android/res, copied over the generated res/) and the
 *   launcher label from capacitor.config.json's appName (`cap sync` does not update it).
 */
import { cpSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { patchGradle, versionCode } from "./android-gradle.mjs";

const main = join(import.meta.dirname, "../android/app/src/main");
const manifestPath = join(main, "AndroidManifest.xml");
if (!existsSync(manifestPath)) {
  console.error("android/ not found. Run `npx cap add android` first.");
  process.exit(1);
}

const DOMAINS = ["root", "file", "database", "sharedpref", "external"];
const excludeAll = DOMAINS.map((d) => `        <exclude domain="${d}" path="." />`).join("\n");
const rules = `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by scripts/android-harden.mjs. Health data never leaves the phone except as an encrypted manual backup. -->
<data-extraction-rules>
    <cloud-backup>
${excludeAll}
    </cloud-backup>
    <device-transfer>
${excludeAll}
    </device-transfer>
</data-extraction-rules>
`;
mkdirSync(join(main, "res/xml"), { recursive: true });
writeFileSync(join(main, "res/xml/data_extraction_rules.xml"), rules);

let manifest = readFileSync(manifestPath, "utf8");
const app = /<application\b[^>]*>/.exec(manifest);
if (!app) {
  console.error("No <application> tag in AndroidManifest.xml");
  process.exit(1);
}
let tag = app[0];
const setAttr = (name, value) => {
  const re = new RegExp(`android:${name}="[^"]*"`);
  tag = re.test(tag) ? tag.replace(re, `android:${name}="${value}"`) : tag.replace(/<application\b/, `<application\n        android:${name}="${value}"`);
};
setAttr("allowBackup", "false");
setAttr("fullBackupContent", "false");
setAttr("dataExtractionRules", "@xml/data_extraction_rules");
manifest = manifest.replace(app[0], tag);
writeFileSync(manifestPath, manifest);

console.log("Android backup disabled: allowBackup=false, fullBackupContent=false, data_extraction_rules excludes everything.");

// The app version (package.json is the one source; Settings > About shows it) and the release
// signing config: scripts/android-gradle.mjs.
const gradlePath = join(import.meta.dirname, "../android/app/build.gradle");
const { version } = JSON.parse(readFileSync(join(import.meta.dirname, "../package.json"), "utf8"));
writeFileSync(gradlePath, patchGradle(readFileSync(gradlePath, "utf8"), version));
console.log(`Android version set to ${version} (versionCode ${versionCode(version)}); release signing reads HEALTH_KEYSTORE* from the environment.`);

// The launcher icon and label. Capacitor's default foreground PNGs are removed so the adaptive
// icon can only use the Even vector (resources/logo.svg is the source of every size).
for (const dir of ["mdpi", "hdpi", "xhdpi", "xxhdpi", "xxxhdpi"]) rmSync(join(main, `res/mipmap-${dir}/ic_launcher_foreground.png`), { force: true });
cpSync(join(import.meta.dirname, "../resources/android/res"), join(main, "res"), { recursive: true });
const { appName } = JSON.parse(readFileSync(join(import.meta.dirname, "../capacitor.config.json"), "utf8"));
const stringsPath = join(main, "res/values/strings.xml");
const label = appName.replace(/&/g, "&amp;").replace(/</g, "&lt;");
writeFileSync(
  stringsPath,
  readFileSync(stringsPath, "utf8").replace(/(<string name="(?:app_name|title_activity_main)">)[^<]*(<\/string>)/g, `$1${label}$2`),
);
console.log(`Launcher icon and label set: ${appName}.`);
